# Column headers
HEADERS = [
    "SI No", "Test Case Name", "Test Description", "Test Objective", "Test Category",
    "Test Steps", "Expected Results", "Register Name", "Register Offset (Hex)",
    "Register Block", "Block Base Offset (Hex)", "Absolute Register Address (Hex)",
    "Fields Accessed", "Bit Range", "Field Width (bits)", "Access Type", "Reset Value",
    "Read/Write Operation", "Values Written", "IP_NAME", "Source File",
    "Macro Name in Code", "Notes"
]

def create_workbook():
    IST = timezone(timedelta(hours=5, minutes=30))
    now = datetime.now(IST)
    filename = f"PCIE_TestPlan_{now.strftime('%Y%m%d')}_{now.strftime('%H%M%S')}.xlsx"
    
    wb = Workbook()
    
    # TestPlan sheet
    ws_tp = wb.active
    ws_tp.title = "TestPlan"
    
    # MetaData sheet
    ws_md = wb.create_sheet("MetaData")
    ws_md.sheet_state = 'veryHidden'
    
    # Formatting
    header_font = Font(bold=True, color="FFFFFF", size=11)
    header_fill = PatternFill(start_color="4472C4", end_color="4472C4", fill_type="solid")
    wrap_align = Alignment(wrap_text=True, vertical="top")
    
    # Write headers to both sheets
    for col_idx, header in enumerate(HEADERS, 1):
        # TestPlan
        cell_tp = ws_tp.cell(row=1, column=col_idx, value=header)
        cell_tp.font = header_font
        cell_tp.fill = header_fill
        cell_tp.alignment = wrap_align
        # MetaData
        cell_md = ws_md.cell(row=1, column=col_idx, value=header)
        cell_md.font = header_font
        cell_md.fill = header_fill
        cell_md.alignment = wrap_align
    
    # Write data rows
    for row_idx, row_data in enumerate(json_data, 2):
        for col_idx, header in enumerate(HEADERS, 1):
            value = row_data.get(header, "")
            if value is None:
                value = ""
            # TestPlan
            cell_tp = ws_tp.cell(row=row_idx, column=col_idx, value=str(value))
            cell_tp.alignment = wrap_align
            # MetaData
            cell_md = ws_md.cell(row=row_idx, column=col_idx, value=str(value))
            cell_md.alignment = wrap_align
    
    # Freeze first row
    ws_tp.freeze_panes = "A2"
    ws_md.freeze_panes = "A2"
    
    # Auto-size columns
    max_widths = {"Test Description": 60, "Test Steps": 60, "Expected Results": 50,
                  "Test Objective": 50, "Notes": 50, "Fields Accessed": 40}
    
    for sheet in [ws_tp, ws_md]:
        for col_idx, header in enumerate(HEADERS, 1):
            max_len = len(str(header))
            for row in range(2, len(json_data) + 2):
                cell_val = str(sheet.cell(row=row, column=col_idx).value or "")
                lines = cell_val.split('\n')
                for line in lines:
                    max_len = max(max_len, len(line))
            col_letter = get_column_letter(col_idx)
            cap = max_widths.get(header, 35)
            width = min(max_len + 2, cap)
            sheet.column_dimensions[col_letter].width = max(width, 12)
    
    # Save
    script_dir = os.path.dirname(os.path.abspath(__file__))
    filepath = os.path.join(script_dir, filename)
    wb.save(filepath)
    
    # Validate
    assert os.path.exists(filepath), f"File not found: {filepath}"
    assert os.path.getsize(filepath) > 0, "File is empty"
    wb2 = load_workbook(filepath)
    assert "TestPlan" in wb2.sheetnames, "TestPlan sheet missing"
    assert "MetaData" in wb2.sheetnames, "MetaData sheet missing"
    tp_rows = wb2["TestPlan"].max_row - 1
    md_rows = wb2["MetaData"].max_row - 1
    assert tp_rows == 68, f"Expected 68 rows, got {tp_rows}"
    assert md_rows == 68, f"Expected 68 metadata rows, got {md_rows}"
    wb2.close()
    
    print(f"SUCCESS: {filename}")
    print(f"Path: {filepath}")
    print(f"Size: {os.path.getsize(filepath)} bytes")
    print(f"TestPlan rows: {tp_rows}")
    print(f"MetaData rows: {md_rows}")
    print(f"Validation: PASSED")
    return filepath, filename

if __name__ == "__main__":
    create_workbook()
